namespace detail {

struct Any {
  template <class U>
  operator U();
};

template <class T, std::size_t N>
consteval auto aggregate_initializable_at_least() {
  return []<size_t... I>(std::index_sequence<I...>) -> auto {
    return (requires { T{((void)I, Any{})...}; });
  }(std::make_index_sequence<N>{});
}

template <class T, std::size_t Max = 65, std::size_t Min = 0>
consteval auto aggregate_initializable() -> std::size_t {
  if constexpr (Max == Min) {
    return Min;
  }
  if constexpr (Max == Min + 1) {
    return aggregate_initializable_at_least<T, Max>() ? Max : Min;
  }
  if constexpr (aggregate_initializable_at_least<T, (Max + Min) / 2>()) {
    return aggregate_initializable<T, Max, (Max + Min) / 2>();
  } else {
    return aggregate_initializable<T, (Max + Min) / 2, Min>();
  }
}

}  // namespace detail

